(assert (= "1.12.6" (clojure-version)))
(let [source "(let [x (+ 3000000000 5) y (+ 1.25 0.5) f (fn [] (+ x y))] (f))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "3.00000000675E9" actual)))
(let [source "(let [f (fn [] 127.1)] (byte (f)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "127" actual)))
(let [source "(let [f (fn [] 2147483647.9)] (int (f)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "2147483647" actual)))
(let [source "(let [f (fn [] (unchecked-float 2147483648.0))] (try (int (f)) (catch Throwable e :error)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= ":error" actual)))
(let [source "(let [f (fn [x] (if x 1.5 2.5))] [(f true) (f false)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[1.5 2.5]" actual)))
(let [source "(let [x -0.0 f (fn [] x)] [(f) (/ 1.0 (f))])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[-0.0 ##-Inf]" actual)))
(let [source "(let [x ##NaN f (fn [] (+ x 0.0)) a (f) b (f)] [(= a b) (== a b) (identical? a b)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[false false false]" actual)))
(let [source "(let [x 9223372036854775807 f (fn [] (inc x))] (try (f) (catch Throwable e (ex-message e))))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "\"long overflow\"" actual)))
(let [source "(let [events (atom []) f (fn [x y] (swap! events conj :body) (+ x y))] [(f (do (swap! events conj :first) 1) (do (swap! events conj :second) 2)) @events])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3 [:first :second :body]]" actual)))
(let [source "(let [events (atom []) f (fn [] (swap! events conj :body) 7)] [(f) (f) @events])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[7 7 [:body :body]]" actual)))
(let [source "(let [f (fn [^long x] x)] (try (f 1.0E300) (catch Throwable e :error)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= ":error" actual)))
(let [source "(let [f (fn ^long [] (identity 1.0E300))] (f))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "9223372036854775807" actual)))
(let [source "(let [f (fn [n] (loop [i n acc 0] (if (zero? i) acc (recur (dec i) (+ acc i)))))] (f 5))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "15" actual)))
(let [source "(let [x 3000000000 f (fn [n] (if (zero? n) x (+ x n)))] [(f 0) (f 3)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[3000000000 3000000003]" actual)))
(let [source "(let [f (fn [x] x)] (try (f 1 2) (catch Throwable e :arity)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= ":arity" actual)))
(let [source "(let [x 3000000000 f (fn [] x)] ((identity f)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "3000000000" actual)))
(let [source "(let [x 3000000000 f (fn [] x) out [f]] ((nth out 0)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "3000000000" actual)))
(let [source "(let [x 3000000000 f (fn [] x)] (loop [i 0 acc 0] (if (< i 4) (recur (inc i) (+ acc (f))) acc)))" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "12000000000" actual)))
(let [source "(let [f (fn [x] (try (if x (throw :bad) 1) (catch Throwable e 2) (finally nil)))] [(f false) (f true)])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[1 2]" actual)))
(let [source "(let [events (atom []) f (fn [] (swap! events conj :body) 7)] [(try (do (f) (throw :bad)) (catch Throwable e (f))) @events])" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= "[7 [:body :body]]" actual)))
